(1333462, 170903, 34481, '<td valign="top">It would be a stronger image if the bird was in sharper focus.</td>', 'It would be a stronger image if the bird was in sharper focus.', '2005-04-27 14:31:12.000000', NULL, 1),
(1333463, 170044, 34481, '<td valign="top">Too many distracting elements.</td>', 'Too many distracting elements.', '2005-04-27 14:31:30.000000', NULL, 1),
