(1333645, 169348, 37008, '<td valign="top">I feel this image had a central subject that occupied a small portion of the image.</td>', 'I feel this image had a central subject that occupied a small portion of the image.', '2005-04-27 14:58:21.000000', NULL, 1),
(1333647, 169794, 37008, '<td valign="top">I feel this image had a central subject that occupied a small portion of the image.</td>', 'I feel this image had a central subject that occupied a small portion of the image.', '2005-04-27 14:59:18.000000', NULL, 1),
(1333649, 169266, 35645, '<td valign="top">The background is too busy for me too feel it meets the challenge description. If they''d been silhouetted against the sky, a cliff face, or a dam it would have made this a ''cleaner'' pic and may have fit the challenge better. Also, the fishermen are a bit out of focus (which detracts from their ''stage presence'' as the main subject) and your horizon is slightly tilted.</td>', 'The background is too busy for me too feel it meets the challenge description. If they''d been silhouetted against the sky, a cliff face, or a dam it would have made this a ''cleaner'' pic and may have fit the challenge better. Also, the fishermen are a bit out of focus (which detracts from their ''stage presence'' as the main subject) and your horizon is slightly tilted.', '2005-04-27 14:59:48.000000', NULL, 1),
(1333650, 171190, 37008, '<td valign="top">I feel this image had a central subject that occupied a small portion of the image.</td>', 'I feel this image had a central subject that occupied a small portion of the image.', '2005-04-27 14:59:49.000000', NULL, 1),
