(1334103, 171085, 33379, '<td valign="top">very hidden</td>', 'very hidden', '2005-04-27 16:56:29.000000', NULL, 1),
(1334104, 170570, 34659, '<td valign="top">Sorry, but this just doesn''t do it for me...  It seems very "empty".  I know that a wisp of cloud can certainly be beautiful, but this one doesn''t seem to hold anything special.  (Sorry - I hate to be negative, but it looks like you cropped it from a much larger image that was probably quite nice.)</td>', 'Sorry, but this just doesn''t do it for me...  It seems very "empty".  I know that a wisp of cloud can certainly be beautiful, but this one doesn''t seem to hold anything special.  (Sorry - I hate to be negative, but it looks like you cropped it from a much larger image that was probably quite nice.)', '2005-04-27 16:56:31.000000', NULL, 1),
(1334105, 171284, 29537, '<td valign="top">the subject isn''t occupying a very small portion of the image space.</td>', 'the subject isn''t occupying a very small portion of the image space.', '2005-04-27 16:56:53.000000', NULL, 1),
(1334110, 170337, 35739, '<td valign="top">Well done!  You met the challenge.  Artistic value is very good.  Not sure about the background colors but you have done a fine job.</td>', 'Well done!  You met the challenge.  Artistic value is very good.  Not sure about the background colors but you have done a fine job.', '2005-04-27 16:57:56.000000', NULL, 1),
