(1334174, 171134, 24454, '<td valign="top">I like it.  I love the stark white background.</td>', 'I like it.  I love the stark white background.', '2005-04-27 17:18:29.000000', NULL, 1),
(1334175, 169761, 25397, '<td valign="top">My favourite of the challenge so far, very coo<br/>I like how you used the isolated feeling to complement the challenge<br/> <br/>(I''ve added it to favourites)</td>', 'My favourite of the challenge so far, very cooI like how you used the isolated feeling to complement the challenge (I''ve added it to favourites)', '2005-04-27 17:18:32.000000', NULL, 1),
(1334176, 169852, 30508, '<td valign="top">There doesn''t seem to be any particular center of focus in this image.  The sky is beautiful, but the trees in the foreground are a bit out of focus.  If there were something of interest amongst those trees, it might be better.</td>', 'There doesn''t seem to be any particular center of focus in this image.  The sky is beautiful, but the trees in the foreground are a bit out of focus.  If there were something of interest amongst those trees, it might be better.', '2005-04-27 17:18:34.000000', NULL, 1),
(1334177, 169916, 24454, '<td valign="top">I like this a lot.   I like the colors, I like the composition.   Good luck.</td>', 'I like this a lot.   I like the colors, I like the composition.   Good luck.', '2005-04-27 17:19:11.000000', NULL, 1),
