(1335203, 171000, 34390, '<td valign="top">Nice shot of this little bird!</td>', 'Nice shot of this little bird!', '2005-04-27 21:23:51.000000', NULL, 1),
(1335204, 170451, 34390, '<td valign="top">Very pretty--spring is here!</td>', 'Very pretty--spring is here!', '2005-04-27 21:24:09.000000', NULL, 1),
(1335207, 169962, 34390, '<td valign="top">I''m glad it''s him up there and not me! Great shot.</td>', 'I''m glad it''s him up there and not me! Great shot.', '2005-04-27 21:25:19.000000', NULL, 1),
(1335209, 170550, 33947, '<td valign="top">Very creative. Wish there was a bit more definition between your face and the white background.</td>', 'Very creative. Wish there was a bit more definition between your face and the white background.', '2005-04-27 21:25:21.000000', NULL, 1),
