(1335655, 169658, 22496, '<td valign="top">Complementary colours too...</td>', 'Complementary colours too...', '2005-04-27 23:21:35.000000', NULL, 1),
(1335656, 170712, 31541, '<td valign="top">The green leaves came out great.  The flowers look a little out of focus for being the focal point (imo).</td>', 'The green leaves came out great.  The flowers look a little out of focus for being the focal point (imo).', '2005-04-27 23:21:40.000000', NULL, 1),
(1335657, 171223, 34134, '<td valign="top">Sorry, but this looks way over-processed and unnatural. Also, it would benefit to move the subject off from dead center.</td>', 'Sorry, but this looks way over-processed and unnatural. Also, it would benefit to move the subject off from dead center.', '2005-04-27 23:21:44.000000', NULL, 1),
