INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1339645, 170428, 1024, '<td valign="top">Wow, great shot.  That road makes me want to just get into a sports car and drive :-)</td>', 'Wow, great shot.  That road makes me want to just get into a sports car and drive :-)', '2005-04-28 20:07:17.000000', NULL, 1),
(1339651, 170912, 1024, '<td valign="top">Great DOF, good capture.</td>', 'Great DOF, good capture.', '2005-04-28 20:08:46.000000', NULL, 1),
(1339654, 169715, 1024, '<td valign="top">This photo is actually a little "busy" for a minimalist challenge.  You subject sort of gets lost amid all the folidge</td>', 'This photo is actually a little "busy" for a minimalist challenge.  You subject sort of gets lost amid all the folidge', '2005-04-28 20:09:41.000000', NULL, 1),
(1339658, 171334, 34103, '<td valign="top">Great macro shot.</td>', 'Great macro shot.', '2005-04-28 20:10:28.000000', NULL, 1),
(1339660, 170906, 17837, '<td valign="top">I feel as if the subject here is the entire church, not sure if that is correct however. Since this is the case, I feel that you do not meet the requirements of the photo, since it takes up about 40% of the given frame.</td>', 'I feel as if the subject here is the entire church, not sure if that is correct however. Since this is the case, I feel that you do not meet the requirements of the photo, since it takes up about 40% of the given frame.', '2005-04-28 20:10:53.000000', NULL, 1),
