(1339680, 169522, 33732, '<td valign="top">Not very interresting.</td>', 'Not very interresting.', '2005-04-28 20:13:17.000000', NULL, 1),
(1339681, 169901, 34103, '<td valign="top">Super nice job.</td>', 'Super nice job.', '2005-04-28 20:13:21.000000', NULL, 1),
(1339683, 171271, 33732, '<td valign="top">Depth of field?</td>', 'Depth of field?', '2005-04-28 20:13:40.000000', NULL, 1),
