(1340979, 169059, 36604, '<td valign="top">The shadow across the head is distracting, and the plain background somewhat tedious.</td>', 'The shadow across the head is distracting, and the plain background somewhat tedious.', '2005-04-29 02:16:55.000000', NULL, 1),
(1340981, 170250, 20324, '<td valign="top">nice warm colors, but the picture itself is not very interesting in my opinion. it doesnt portray the subject very well. (6)</td>', 'nice warm colors, but the picture itself is not very interesting in my opinion. it doesnt portray the subject very well. (6)', '2005-04-29 02:17:51.000000', NULL, 1),
