(1341991, 171128, 26505, '<td valign="top">very nice. good choice of the greenery for the background..it really sets this image apart from all the other "flower" ones.</td>', 'very nice. good choice of the greenery for the background..it really sets this image apart from all the other "flower" ones.', '2005-04-29 10:08:26.000000', NULL, 1),
(1341992, 170429, 29477, '<td valign="top">I was glad to see this photo validated ias it is a great entry to this challenge.  Well done and Good Luck.</td>', 'I was glad to see this photo validated ias it is a great entry to this challenge.  Well done and Good Luck.', '2005-04-29 10:08:54.000000', NULL, 1),
(1341994, 169155, 26505, '<td valign="top">If you look at this too long you really get dizzy! But it is a nice shot capturing minimalism very well!</td>', 'If you look at this too long you really get dizzy! But it is a nice shot capturing minimalism very well!', '2005-04-29 10:09:46.000000', NULL, 1),
