(1342008, 171194, 26505, '<td valign="top">Very nice! Your border looks really great here...and that eye is gorgeous!</td>', 'Very nice! Your border looks really great here...and that eye is gorgeous!', '2005-04-29 10:13:55.000000', NULL, 1),
(1342013, 171180, 26505, '<td valign="top">nice job! the color of the boat really adds to this shot! I really like it!</td>', 'nice job! the color of the boat really adds to this shot! I really like it!', '2005-04-29 10:14:50.000000', NULL, 1),
