INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1357192, 170314, 145, '<td valign="top">The reflection of the hand is distracting for me. 5</td>', 'The reflection of the hand is distracting for me. 5', '2005-05-03 23:55:00.000000', NULL, 1),
